actions.script:
// Fills phonebooks.com's removal form with the street address from the
// profile page. phonebooks only matches a record on its exact DOB or street
// address, and the street is not in the search results, only on the profile.
//
// Called as function (userProfile, root) with dataSource: extractedProfile,
// so userProfile is the matched profile and root is the opt-out page.

// Sets an input's value the way a user typing would, so the page's form
// framework registers it.
const valueSetter = Object.getOwnPropertyDescriptor(
  HTMLInputElement.prototype,
  "value",
).set;

function fillInput(form, selector, value) {
  const input = form.querySelector(selector);
  if (!input) throw new Error("input not found: " + selector);

  input.dispatchEvent(new Event("keydown", { bubbles: true }));
  valueSetter.call(input, value);
  for (const type of ["input", "keyup", "change"]) {
    input.dispatchEvent(new Event(type, { bubbles: true }));
  }
  input.blur();
}

// Fetches the profile page and returns its current address as
// { street, city, state, zip }.
async function fetchCurrentAddress(profileUrl) {
  const res = await fetch(profileUrl, { credentials: "include" });
  if (!res.ok) throw new Error("profile fetch returned " + res.status);
  const doc = new DOMParser().parseFromString(await res.text(), "text/html");

  // The address link reads "<street> <city>, <ST> <zip>", with no separator
  // between street and city.
  const addressLine = (
    (doc.querySelector("ul.current-address a") || {}).textContent || ""
  ).trim();
  const address = addressLine.match(
    /^(.*),\s*([A-Z]{2})\s+(\d{5})(?:-\d{4})?$/,
  );

  // "Lives in <city>, <ST>" gives the city, which tells us where the street ends.
  const pageText = (doc.body && doc.body.textContent) || "";
  const livesIn = pageText.match(
    /lives in[:\s]*([A-Za-z .'-]+?),\s*([A-Z]{2})\b/i,
  );

  if (!address || !livesIn) {
    throw new Error("current address not found on profile page");
  }

  const city = livesIn[1].trim();
  const streetAndCity = address[1].trim();
  if (!streetAndCity.toLowerCase().endsWith(" " + city.toLowerCase())) {
    throw new Error("could not split street from city");
  }
  const street = streetAndCity
    .slice(0, streetAndCity.length - city.length)
    .trim();

  return { street, city, state: address[2], zip: address[3] };
}

return (async () => {
  const form = root.querySelector(".v-opt-out-removal form");
  if (!form) throw new Error("removal form not found");

  const profileUrl = userProfile && userProfile.profileUrl;
  if (!profileUrl) throw new Error("extracted profile has no profileUrl");

  const { street, city, state, zip } = await fetchCurrentAddress(profileUrl);

  fillInput(form, "input#address[type='text']", street);
  fillInput(form, "#city", city);
  fillInput(form, "#state", state);
  fillInput(form, "#zip", zip);
})();
